               v_a(1)*x107 + v_a(2)*(x121*x68 - x121*x73 - x122*x27 + x122*x29 - x123*x71 + &
               x123*x74 + 6.0_wp*x48 + x89) + v_a(3)*x120
            x125 = x1*x2
            x126 = x102 + x125*x68 - x125*x72 - x125*x73 + x125*x75 + x15 + x96 + x98
            x127 = v_a(1)*x109 + v_a(2)*x120 + v_a(3)*x126
            x128 = d_a(2)*x65
            x129 = x119 + x128*x68 - x128*x72 - x128*x73 + x128*x75
            x130 = v_a(1)*x112 + v_a(2)*x126 + v_a(3)*x129
            x131 = (d_a(3)*d_a(3)*d_a(3)*d_a(3))
            x132 = 18.0_wp*x2
            x133 = 15.0_wp*x131
            x134 = &
               v_a(1)*x115 + v_a(2)*x129 + v_a(3)*(x131*x68 - x131*x73 - x132*x27 + x132*x29 - &
               x133*x71 + x133*x74 + 6.0_wp*x54 + x89)
            tg0 = tg0 + (-d_a(1)*v_a(1)*x5 - d_a(2)*v_a(2)*x5 - d_a(3)*v_a(3)*x5)
            tg1_r(1) = tg1_r(1) + (-x16)
            tg1_r(2) = tg1_r(2) + (-x18)
            tg1_r(3) = tg1_r(3) + (-x19)
            tg2_rr(1, 1) = tg2_rr(1, 1) + (-x41)
            t_tg2_rr_01 = -x53
            tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
            tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
            t_tg2_rr_02 = -x58
            tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
            tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
            tg2_rr(2, 2) = tg2_rr(2, 2) + (-x62)
            t_tg2_rr_12 = -x64
            tg2_rr(2, 3) = tg2_rr(2, 3) + t_tg2_rr_12
            tg2_rr(3, 2) = tg2_rr(3, 2) + t_tg2_rr_12
            tg2_rr(3, 3) = tg2_rr(3, 3) + (-x67)
            tg3_rrr(1, 1, 1) = tg3_rrr(1, 1, 1) + (-x90)
            t_tg3_rrr_001 = -x100
            tg3_rrr(1, 1, 2) = tg3_rrr(1, 1, 2) + t_tg3_rrr_001
            tg3_rrr(1, 2, 1) = tg3_rrr(1, 2, 1) + t_tg3_rrr_001
            tg3_rrr(2, 1, 1) = tg3_rrr(2, 1, 1) + t_tg3_rrr_001
            t_tg3_rrr_002 = -x104
            tg3_rrr(1, 1, 3) = tg3_rrr(1, 1, 3) + t_tg3_rrr_002
            tg3_rrr(1, 3, 1) = tg3_rrr(1, 3, 1) + t_tg3_rrr_002
            tg3_rrr(3, 1, 1) = tg3_rrr(3, 1, 1) + t_tg3_rrr_002
            t_tg3_rrr_011 = -x110
            tg3_rrr(1, 2, 2) = tg3_rrr(1, 2, 2) + t_tg3_rrr_011
            tg3_rrr(2, 1, 2) = tg3_rrr(2, 1, 2) + t_tg3_rrr_011
            tg3_rrr(2, 2, 1) = tg3_rrr(2, 2, 1) + t_tg3_rrr_011
            t_tg3_rrr_012 = -x113
            tg3_rrr(1, 2, 3) = tg3_rrr(1, 2, 3) + t_tg3_rrr_012
            tg3_rrr(1, 3, 2) = tg3_rrr(1, 3, 2) + t_tg3_rrr_012
            tg3_rrr(2, 1, 3) = tg3_rrr(2, 1, 3) + t_tg3_rrr_012
            tg3_rrr(2, 3, 1) = tg3_rrr(2, 3, 1) + t_tg3_rrr_012
            tg3_rrr(3, 1, 2) = tg3_rrr(3, 1, 2) + t_tg3_rrr_012
            tg3_rrr(3, 2, 1) = tg3_rrr(3, 2, 1) + t_tg3_rrr_012
            t_tg3_rrr_022 = -x116
            tg3_rrr(1, 3, 3) = tg3_rrr(1, 3, 3) + t_tg3_rrr_022
            tg3_rrr(3, 1, 3) = tg3_rrr(3, 1, 3) + t_tg3_rrr_022
            tg3_rrr(3, 3, 1) = tg3_rrr(3, 3, 1) + t_tg3_rrr_022
            tg3_rrr(2, 2, 2) = tg3_rrr(2, 2, 2) + (-x124)
            t_tg3_rrr_112 = -x127
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = -x130
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = tg3_rrr(3, 3, 3) + (-x134)
            hvp0_a(1) = hvp0_a(1) + (x16)
            hvp0_a(2) = hvp0_a(2) + (x18)
            hvp0_a(3) = hvp0_a(3) + (x19)
            hvp1_r_a(1, 1) = hvp1_r_a(1, 1) + (x41)
            hvp1_r_a(1, 2) = hvp1_r_a(1, 2) + (x53)
            hvp1_r_a(1, 3) = hvp1_r_a(1, 3) + (x58)
            hvp1_r_a(2, 1) = hvp1_r_a(2, 1) + (x53)
            hvp1_r_a(2, 2) = hvp1_r_a(2, 2) + (x62)
            hvp1_r_a(2, 3) = hvp1_r_a(2, 3) + (x64)
            hvp1_r_a(3, 1) = hvp1_r_a(3, 1) + (x58)
            hvp1_r_a(3, 2) = hvp1_r_a(3, 2) + (x64)
            hvp1_r_a(3, 3) = hvp1_r_a(3, 3) + (x67)
            hvp2_rr_a(1, 1, 1) = hvp2_rr_a(1, 1, 1) + (x90)
            hvp2_rr_a(1, 1, 2) = hvp2_rr_a(1, 1, 2) + (x100)
            hvp2_rr_a(1, 1, 3) = hvp2_rr_a(1, 1, 3) + (x104)
            t_hvp2_rr_a_010 = x100
            hvp2_rr_a(1, 2, 1) = hvp2_rr_a(1, 2, 1) + t_hvp2_rr_a_010
            hvp2_rr_a(2, 1, 1) = hvp2_rr_a(2, 1, 1) + t_hvp2_rr_a_010
            t_hvp2_rr_a_011 = x110
            hvp2_rr_a(1, 2, 2) = hvp2_rr_a(1, 2, 2) + t_hvp2_rr_a_011
            hvp2_rr_a(2, 1, 2) = hvp2_rr_a(2, 1, 2) + t_hvp2_rr_a_011
            t_hvp2_rr_a_012 = x113
            hvp2_rr_a(1, 2, 3) = hvp2_rr_a(1, 2, 3) + t_hvp2_rr_a_012
            hvp2_rr_a(2, 1, 3) = hvp2_rr_a(2, 1, 3) + t_hvp2_rr_a_012
            t_hvp2_rr_a_020 = x104
            hvp2_rr_a(1, 3, 1) = hvp2_rr_a(1, 3, 1) + t_hvp2_rr_a_020
            hvp2_rr_a(3, 1, 1) = hvp2_rr_a(3, 1, 1) + t_hvp2_rr_a_020
            t_hvp2_rr_a_021 = x113
            hvp2_rr_a(1, 3, 2) = hvp2_rr_a(1, 3, 2) + t_hvp2_rr_a_021
            hvp2_rr_a(3, 1, 2) = hvp2_rr_a(3, 1, 2) + t_hvp2_rr_a_021
            t_hvp2_rr_a_022 = x116
            hvp2_rr_a(1, 3, 3) = hvp2_rr_a(1, 3, 3) + t_hvp2_rr_a_022
            hvp2_rr_a(3, 1, 3) = hvp2_rr_a(3, 1, 3) + t_hvp2_rr_a_022
            hvp2_rr_a(2, 2, 1) = hvp2_rr_a(2, 2, 1) + (x110)
            hvp2_rr_a(2, 2, 2) = hvp2_rr_a(2, 2, 2) + (x124)
            hvp2_rr_a(2, 2, 3) = hvp2_rr_a(2, 2, 3) + (x127)
            t_hvp2_rr_a_120 = x113
            hvp2_rr_a(2, 3, 1) = hvp2_rr_a(2, 3, 1) + t_hvp2_rr_a_120
            hvp2_rr_a(3, 2, 1) = hvp2_rr_a(3, 2, 1) + t_hvp2_rr_a_120
            t_hvp2_rr_a_121 = x127
            hvp2_rr_a(2, 3, 2) = hvp2_rr_a(2, 3, 2) + t_hvp2_rr_a_121
            hvp2_rr_a(3, 2, 2) = hvp2_rr_a(3, 2, 2) + t_hvp2_rr_a_121
            t_hvp2_rr_a_122 = x130
            hvp2_rr_a(2, 3, 3) = hvp2_rr_a(2, 3, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 2, 3) = hvp2_rr_a(3, 2, 3) + t_hvp2_rr_a_122
            hvp2_rr_a(3, 3, 1) = hvp2_rr_a(3, 3, 1) + (x116)
            hvp2_rr_a(3, 3, 2) = hvp2_rr_a(3, 3, 2) + (x130)
            hvp2_rr_a(3, 3, 3) = hvp2_rr_a(3, 3, 3) + (x134)
         end block
      end select

   end subroutine cfc_atomic_hvp_eval_faded

   pure module subroutine cfc_pair_hvp_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                           v_a, v_b, max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr, &
                                           hvp0_a, hvp0_b, hvp1_r_a, hvp1_r_b, hvp2_rr_a, &
                                           hvp2_rr_b, sg_a, sg_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A v_A . d/dr_A of the order-0 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg0
      !> sum_A v_A . d/dr_A of the order-1 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A v_A . d/dr_A of the order-2 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A v_A . d/dr_A of the order-3 spatial derivative (free by-product of the HVP; see the
      !> note above)
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-0 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp0_a(3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-0 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp0_b(3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-1 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp1_r_a(3, 3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-1 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp1_r_b(3, 3)
      !> sum_B v_B . d2/(dr_a dr_B) of the order-2 spatial derivative; trailing index is the
      !> retained nuclear component of atom a
      real(wp), intent(inout) :: hvp2_rr_a(3, 3, 3)
      !> sum_B v_B . d2/(dr_b dr_B) of the order-2 spatial derivative; trailing index is the
      !> retained nuclear component of atom b
      real(wp), intent(inout) :: hvp2_rr_b(3, 3, 3)
      !> Reduced distance sigma = ||d_a||/R_a - 1 of center a
      real(wp), intent(in) :: sg_a
      !> Reduced distance sigma = ||d_b||/R_b - 1 of center b
      real(wp), intent(in) :: sg_b

      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_pair_hvp_eval: fade_width must be positive"
      band_end = fade_start + fade_width
      ! Beyond the band of a center: w = 0, nothing to add
      if (sg_a >= band_end .or. sg_b >= band_end) return
      inv_delta = 1.0_wp/fade_width
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + fj1)
            g_a(2) = &
               fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_b(0) = fj0
            g_b(1) = a2*fj0 + fj1
            g_b(2) = &
               (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2)
            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = c_par*g_a(0)*g_b(0)
            x4 = d_a(1)*d_b(1)
            x5 = d_a(2)*d_b(2)
            x6 = d_a(3)*d_b(3)
            x7 = -x2*(x4 + x5 + x6) + 1.0_wp
            x8 = (x7*x7*x7)
            x9 = 4.0_wp*x8
            x10 = x2*x3*x9
            x11 = (d_a(1)*d_a(1))
            x12 = (d_a(2)*d_a(2))
            x13 = (d_a(3)*d_a(3))
            x14 = x11 + x12 + x13
            x15 = 1.0_wp/sqrt(x14)
            x16 = g_a(1)*x15
            x17 = (x7*x7*x7*x7)
            x18 = c_par*x17
            x19 = g_b(0)*x18
            x20 = x0*x19
            x21 = x16*x20
            x22 = (d_b(1)*d_b(1))
            x23 = (d_b(2)*d_b(2))
            x24 = (d_b(3)*d_b(3))
            x25 = x22 + x23 + x24
            x26 = 1.0_wp/sqrt(x25)
            x27 = g_b(1)*x26
            x28 = g_a(0)*x18
            x29 = x1*x28
            x30 = x27*x29
            x31 = 1.0_wp/(R_b*R_b)
            x32 = 1.0_wp/(R_a*R_a)
            x33 = (x7*x7)
            x34 = 12.0_wp*x3*x33
            x35 = x32*x34
            x36 = x31*x35
            x37 = d_b(1)*x36
            x38 = x16*x18*x2*x27
            x39 = d_a(1)*x38
            x40 = d_a(1)*d_a(2)
            x41 = c_par*x9
            x42 = g_b(0)*x1*x16
            x43 = x41*x42
            x44 = x32*x43
            x45 = d_b(1)*d_b(2)
            x46 = g_a(0)*x0*x27
            x47 = x41*x46
            x48 = x31*x47
            x49 = -x40*x44 - x45*x48
            x50 = d_a(2)*x37 + d_b(2)*x39 + x49
            x51 = d_a(1)*d_a(3)
            x52 = d_b(1)*d_b(3)
            x53 = -x44*x51 - x48*x52
            x54 = d_a(3)*x37 + d_b(3)*x39 + x53
            x55 = x22*x31
            x56 = x11*x32
            x57 = 1.0_wp/x14
            x58 = g_a(2)*x19*x57
            x59 = g_a(1)*x20/(x14*sqrt(x14))
            x60 = 8.0_wp*c_par*x8
            x61 = x4*x60
            x62 = x32*x42
            x63 = d_a(1)*x44
            x64 = d_b(1)*x44
            x65 = &
               c_par*d_a(1)*d_a(2)*g_a(2)*g_b(0)*x17*x32*x57 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*g_a(0)*g_b(0)*x31*x32*x33 - d_a(2)*x64 - d_b(2)*x63 - &
               x40*x59
            x66 = &
               c_par*d_a(1)*d_a(3)*g_a(2)*g_b(0)*x17*x32*x57 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*g_a(0)*g_b(0)*x31*x32*x33 - d_a(3)*x64 - d_b(3)*x63 - &
               x51*x59
            x67 = &
               12.0_wp*c_par*d_a(1)*d_b(1)*g_a(0)*g_b(0)*x31*x32*x33 + &
               c_par*d_a(1)*d_b(1)*g_a(1)*g_b(1)*x0*x1*x15*x17*x26 - x10 - x43*x56 - x47*x55
            x68 = d_b(2)*x36
            x69 = d_b(1)*x38
            x70 = d_a(1)*x68 + d_a(2)*x69 + x49
            x71 = d_a(2)*d_b(3)
            x72 = d_a(2)*d_a(3)
